#!/usr/bin/env python3
"""
test_overall.py — one-command validation for MARK LIV.

This file replaces the old standalone check_*.py scripts. The individual suites
are embedded here so the repository root stays clean, but each suite still runs
in its own Python process with a virtual __file__ in the repository root. That
keeps the old headless/no-Qt isolation properties and lets this runner produce a
single PASS / FAIL / SKIPPED report.

Run everything:  python test_overall.py
Run one suite:   python test_overall.py --suite plugins
Show full logs:  python test_overall.py --verbose
"""
from __future__ import annotations

import argparse
import base64
import os
import re
import tempfile
import subprocess
import sys
import time
import zlib
from dataclasses import dataclass
from pathlib import Path

for _stream in ("stdout", "stderr"):
    try:
        getattr(sys, _stream).reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

REPO = Path(__file__).resolve().parent
SUITE_ORDER = [('compileall', 'python -m compileall -q .'), ('config_manager', 'atomic config write smoke'), ('wake_word', 'embedded wake_word'), ('wake_isolation', 'embedded wake_isolation'), ('session_memory', 'embedded session_memory'), ('dashboard_auth', 'embedded dashboard_auth'), ('plugins', 'embedded plugins'), ('silence', 'embedded silence'), ('setup_cli', 'embedded setup_cli')]
SUITE_SOURCES = {'wake_word': '', 'wake_isolation': '', 'session_memory': '', 'dashboard_auth': '', 'plugins': '', 'silence': '',
 'setup_cli': '',
}

CONFIG_MANAGER_SMOKE = 'import json\nimport tempfile\nfrom pathlib import Path\n\nimport memory.config_manager as cm\n\nwith tempfile.TemporaryDirectory(prefix="markliv-config-") as td:\n    old_file, old_dir = cm.CONFIG_FILE, cm.CONFIG_DIR\n    cm.CONFIG_DIR = Path(td)\n    cm.CONFIG_FILE = Path(td) / "api_keys.json"\n    try:\n        cm.save_api_keys("abc123456789012345")\n        cm.save_assistant_config("Jarvis", "Jonas")\n        cm.save_voice("Puck")\n        cm.save_wake_word_enabled(True)\n        cm.save_push_to_talk_enabled(True)\n        cm.save_dashboard_lan_enabled(False)\n        cm.save_turn_tuning({"enabled": True, "silence_ms": 600})\n        cm.save_proactive_audio_enabled(False)\n        cm.save_media_resolution("high")\n        cm.save_brief_enabled(False)\n        cm.save_input_device("Mic")\n        cm.save_output_device("Speaker")\n        cm.save_plugin_config("telegram_remote", {"start_on_launch": True})\n        cm.save_plugin_enabled("telegram_remote", False)\n        data = json.loads(cm.CONFIG_FILE.read_text(encoding="utf-8"))\n        checks = [\n            ("api key survived", data.get("gemini_api_key") == "abc123456789012345"),\n            ("assistant/user survived", data.get("assistant_name") == "Jarvis" and data.get("user_name") == "Jonas"),\n            ("voice survived", data.get("voice_name") == "Puck"),\n            ("wake flag survived", data.get("wake_word_enabled") is True),\n            ("ptt flag survived", data.get("push_to_talk_enabled") is True),\n            ("turn tuning merged", data.get("turn_tuning", {}).get("silence_ms") == 600),\n            ("plugin config merged", data.get("plugin_config", {}).get("telegram_remote", {}).get("start_on_launch") is True),\n            ("plugin enabled map merged", data.get("plugins_enabled", {}).get("telegram_remote") is False),\n            ("temp files cleaned", not list(Path(td).glob("*.tmp"))),\n        ]\n        # ── a config that cannot be parsed must never be overwritten ────────\n        # Every save is a read-modify-write. A failed read used to return {}, so\n        # one truncated file plus one save silently replaced the API key and\n        # every setting with an almost empty dict.\n        BROKEN = b\'{ "gemini_api_key": "keep-me-1234567890",\'\n        cm.CONFIG_FILE.write_bytes(BROKEN)\n        kept = cm.CONFIG_DIR / "api_keys.corrupt.json"\n        if kept.exists():\n            kept.unlink()\n        checks.append(("corrupt: save_api_keys refuses",\n                       cm.save_api_keys("new-key-1234567890") is False))\n        checks.append(("corrupt: plugin toggle refuses",\n                       cm.save_plugin_enabled("telegram_remote", True) is False))\n        checks.append(("corrupt: plugin config refuses",\n                       cm.save_plugin_config("telegram_remote", {"x": 1}) is False))\n        checks.append(("corrupt: turn tuning refuses",\n                       cm.save_turn_tuning({"silence_ms": 700}) is False))\n        checks.append(("corrupt: original bytes untouched",\n                       cm.CONFIG_FILE.read_bytes() == BROKEN))\n        checks.append(("corrupt: key still recoverable",\n                       b"keep-me-1234567890" in cm.CONFIG_FILE.read_bytes()))\n        checks.append(("corrupt: copy kept for repair",\n                       kept.exists() and b"keep-me-1234567890" in kept.read_bytes()))\n        checks.append(("corrupt: reader degrades to empty",\n                       cm.load_api_keys() == {}))\n\n        # ── an empty file is a fresh install, not corruption ────────────────\n        cm.CONFIG_FILE.write_bytes(b"")\n        checks.append(("empty file: save succeeds",\n                       cm.save_api_keys("fresh-key-1234567890") is True))\n        checks.append(("empty file: value persisted",\n                       json.loads(cm.CONFIG_FILE.read_text(encoding="utf-8"))\n                       .get("gemini_api_key") == "fresh-key-1234567890"))\n\n        # ── write leftovers hold exactly the same secrets as the config ─────\n        try:\n            import subprocess as _sp\n            _repo = Path.cwd()\n            for _rel in ("config/api_keys.json",\n                         "config/api_keys.json.AbCd1234.tmp",\n                         "config/api_keys.corrupt.json"):\n                checks.append(("git ignores " + _rel,\n                               _sp.run(["git", "check-ignore", "-q", _rel],\n                                       cwd=str(_repo)).returncode == 0))\n        except FileNotFoundError:\n            print("  SKIP: git is not available, ignore patterns unchecked")\n        failed = 0\n        for name, ok in checks:\n            print(f"  [{\'PASS\' if ok else \'FAIL\'}] {name}")\n            failed += 0 if ok else 1\n        raise SystemExit(1 if failed else 0)\n    finally:\n        cm.CONFIG_FILE, cm.CONFIG_DIR = old_file, old_dir\n'


@dataclass
class SuiteResult:
    name: str
    file_name: str
    returncode: int
    seconds: float
    stdout: str
    stderr: str
    passed: int
    failed: int
    skipped: int
    status: str


def _source(name: str) -> str:
    return zlib.decompress(base64.b64decode(SUITE_SOURCES[name])).decode("utf-8")


def _run_embedded_suite(name: str) -> int:
    file_label = dict(SUITE_ORDER)[name]
    virtual_file = str(REPO / (file_label.replace('embedded ', 'check_') + '.py' if file_label.startswith('embedded ') else file_label))
    globs = {
        "__name__": "__main__",
        "__file__": virtual_file,
        "__package__": None,
        "__builtins__": __builtins__,
    }
    if str(REPO) not in sys.path:
        sys.path.insert(0, str(REPO))
    try:
        exec(compile(_source(name), virtual_file, "exec"), globs)
        return 0
    except SystemExit as e:
        code = e.code
        if code is None:
            return 0
        if isinstance(code, int):
            return code
        print(code)
        return 1


def _parse_counts(stdout: str, stderr: str, rc: int, name: str) -> tuple[int, int, int, str]:
    text = stdout + "\n" + stderr
    passed = len(re.findall(r"\[PASS\]", text))
    failed = len(re.findall(r"\[FAIL\]", text))
    skipped = len(re.findall(r"(?:^\s*SKIP:|\[SKIP\]|\bSKIP:)", text, flags=re.IGNORECASE | re.MULTILINE))

    # Some legacy checkers predate the [PASS]/[FAIL] convention. Treat their
    # intentional no-feature result as a skipped capability instead of a failed
    # product test, while still failing on a non-zero process exit.
    if name == "compileall" and rc == 0:
        passed = max(passed, 1)
        status = "PASS"
    elif name == "wake_word" and "openwakeword ist NICHT installiert" in text and rc == 0:
        skipped = max(skipped, 1)
        status = "SKIPPED"
    elif name == "silence" and rc == 0:
        # check_silence is an environment probe: it prints the gate/audio report
        # and may legitimately skip PortAudio in CI. The actionable result is
        # still the captured report.
        status = "PASS"
        if "probe skipped" in text.lower():
            skipped = max(skipped, 1)
    elif rc == 0 and failed == 0:
        status = "PASS"
    else:
        status = "FAIL"
        if failed == 0:
            failed = 1
    return passed, failed, skipped, status


def _run_suite(name: str, file_name: str) -> SuiteResult:
    t0 = time.time()
    env = dict(os.environ)
    env["PYTHONIOENCODING"] = "utf-8:replace"
    if name == "compileall":
        proc = subprocess.run(
            [sys.executable, "-m", "compileall", "-q", "."],
            cwd=str(REPO), text=True, encoding="utf-8", errors="replace",
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
        )
    elif name == "config_manager":
        proc = subprocess.run(
            [sys.executable, "-c", CONFIG_MANAGER_SMOKE],
            cwd=str(REPO), text=True, encoding="utf-8", errors="replace",
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
        )
    else:
        proc = subprocess.run(
            [sys.executable, str(Path(__file__).resolve()), "--_run-suite", name],
            cwd=str(REPO), text=True, encoding="utf-8", errors="replace",
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
        )
    seconds = time.time() - t0
    passed, failed, skipped, status = _parse_counts(proc.stdout, proc.stderr, proc.returncode, name)
    return SuiteResult(name, file_name, proc.returncode, seconds,
                       proc.stdout, proc.stderr, passed, failed, skipped, status)


def _print_suite_log(result: SuiteResult, verbose: bool) -> None:
    if verbose or result.status == "FAIL":
        if result.stdout:
            print("\n" + result.stdout.rstrip())
        if result.stderr:
            print("\n[stderr]")
            print(result.stderr.rstrip())
    elif result.status == "SKIPPED":
        # Give the reason, not the whole wall of diagnostic text.
        lines = [ln for ln in result.stdout.splitlines()
                 if "SKIP" in ln.upper() or "NICHT INSTALLIERT" in ln.upper()]
        for ln in lines[:4]:
            print(f"      {ln}")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Run MARK LIV's full validation suite.")
    parser.add_argument("--suite", choices=[name for name, _ in SUITE_ORDER],
                        help="run only one suite")
    parser.add_argument("--verbose", action="store_true",
                        help="print each suite's full output")
    parser.add_argument("--report", default=str(REPO / "_logs" / "test_overall_report.txt"),
                        help="write the final summary to this file atomically")
    parser.add_argument("--_run-suite", choices=[name for name, _ in SUITE_ORDER],
                        help=argparse.SUPPRESS)
    args = parser.parse_args(argv)

    if args._run_suite:
        return _run_embedded_suite(args._run_suite)

    selected = [(n, f) for n, f in SUITE_ORDER if not args.suite or n == args.suite]
    t0 = time.time()
    print("=" * 72)
    print(" MARK LIV — overall validation")
    print("=" * 72)
    print(f"Python: {sys.version.split()[0]}  ({sys.executable})")
    print(f"Repo:   {REPO}")

    results: list[SuiteResult] = []
    for name, file_name in selected:
        print(f"\n── {name} " + "─" * max(0, 60 - len(name)))
        result = _run_suite(name, file_name)
        results.append(result)
        print(f"  [{result.status}] {name} — "
              f"pass={result.passed} fail={result.failed} skip={result.skipped} "
              f"exit={result.returncode} time={result.seconds:.1f}s")
        _print_suite_log(result, args.verbose)

    total_pass = sum(r.passed for r in results)
    total_fail = sum(r.failed for r in results)
    total_skip = sum(r.skipped for r in results)
    failed_suites = [r for r in results if r.status == "FAIL"]
    skipped_suites = [r for r in results if r.status == "SKIPPED"]

    print("\n" + "=" * 72)
    print("OVERALL REPORT")
    print(f"Suites: {len(results)}  Passed suites: {sum(r.status == 'PASS' for r in results)}  "
          f"Failed suites: {len(failed_suites)}  Skipped suites: {len(skipped_suites)}")
    print(f"Checks: pass={total_pass} fail={total_fail} skip={total_skip}  "
          f"Time: {time.time() - t0:.1f}s")
    report_lines = [
        "MARK LIV — overall validation",
        f"Python: {sys.version.split()[0]} ({sys.executable})",
        f"Repo: {REPO}",
        f"Suites: {len(results)}  Passed suites: {sum(r.status == 'PASS' for r in results)}  Failed suites: {len(failed_suites)}  Skipped suites: {len(skipped_suites)}",
        f"Checks: pass={total_pass} fail={total_fail} skip={total_skip}  Time: {time.time() - t0:.1f}s",
        "",
    ]
    report_lines.extend(
        f"{r.status:7} {r.name:15} pass={r.passed} fail={r.failed} skip={r.skipped} exit={r.returncode} time={r.seconds:.1f}s"
        for r in results
    )
    try:
        report_path = Path(args.report)
        report_path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False,
                                         dir=str(report_path.parent),
                                         prefix=report_path.name + ".", suffix=".tmp") as fh:
            fh.write("\n".join(report_lines) + "\n")
            tmp_name = fh.name
        os.replace(tmp_name, report_path)
        print(f"\nReport written to: {report_path}")
    except Exception as e:
        print(f"\nCould not write report file: {e}")

    if failed_suites:
        print("\nFAILED SUITES:")
        for r in failed_suites:
            print(f"  - {r.name}, exit {r.returncode}")
        return 1
    if skipped_suites:
        print("\nSKIPPED SUITES:")
        for r in skipped_suites:
            print(f"  - {r.name}")
    print("\nAll non-skipped suites passed.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
